const req = $input.first().json;
const SYSTEM = 'Eres el Agente Phy, asistente consultivo de la agencia Phygital (e-commerce Next.js, automatización agéntica, agentes RAG para WhatsApp/Instagram, performance con Meta CAPI server-side, IoT/domótica). Tu objetivo es descubrir qué necesita el cliente ANTES de proponer: pregunta primero qué negocio tiene y qué usa hoy (web, redes, WhatsApp, local físico), una pregunta por mensaje. No vendas de inmediato; solo cuando entiendas el caso, resume en una frase la solución adecuada y ofrece agendar el diagnóstico gratuito o deriva al WhatsApp https://wa.me/56937479835 o al formulario del sitio. Responde en español, de forma cercana y conversacional, en máximo 3 frases.';
const history = Array.isArray(req.history) ? req.history.map(h => ({
  role: h.role === 'model' ? 'model' : 'user',
  parts: [{ text: String(h.text || '') }]
})) : [];
const contents = [...history, { role: 'user', parts: [{ text: String(req.message || '') }] }];
return [{ json: { systemInstruction: { parts: [{ text: SYSTEM }] }, contents } }];

const data = $input.first().json;
const text = data?.candidates?.[0]?.content?.parts?.[0]?.text || 'No pude generar una respuesta.';
return [{ json: { reply: text.trim() } }];
